      "content": "<h3>All LinkedList methods at a glance</h3>\n<p><em>n</em> is the number of elements. \"end\" means the first or last element.</p>\n<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse:collapse; width:100%;\">\n<tr><th style=\"text-align:left;\">Method</th><th style=\"text-align:left;\">What it does</th><th style=\"text-align:left;\">Time</th></tr>\n<tr><td><strong>add(e)</strong> / <strong>addLast(e)</strong> / <strong>offer(e)</strong> / <strong>offerLast(e)</strong></td><td>Adds at the end</td><td>O(1)</td></tr>\n<tr><td><strong>addFirst(e)</strong> / <strong>push(e)</strong> / <strong>offerFirst(e)</strong></td><td>Adds at the front</td><td>O(1)</td></tr>\n<tr><td><strong>add(i, e)</strong></td><td>Inserts at index i</td><td>O(n) to find i</td></tr>\n<tr><td><strong>addAll(c)</strong> / <strong>addAll(i, c)</strong></td><td>Adds a whole collection</td><td>O(m) / O(n + m)</td></tr>\n<tr><td><strong>get(i)</strong> / <strong>set(i, e)</strong></td><td>Reads / replaces by index</td><td>O(n)</td></tr>\n<tr><td><strong>getFirst()</strong> / <strong>getLast()</strong> / <strong>element()</strong></td><td>Reads an end (throws if empty)</td><td>O(1)</td></tr>\n<tr><td><strong>peek()</strong> / <strong>peekFirst()</strong> / <strong>peekLast()</strong></td><td>Reads an end (null if empty)</td><td>O(1)</td></tr>\n<tr><td><strong>remove()</strong> / <strong>removeFirst()</strong> / <strong>pop()</strong> / <strong>removeLast()</strong></td><td>Removes an end (throws if empty)</td><td>O(1)</td></tr>\n<tr><td><strong>poll()</strong> / <strong>pollFirst()</strong> / <strong>pollLast()</strong></td><td>Removes an end (null if empty)</td><td>O(1)</td></tr>\n<tr><td><strong>remove(i)</strong> / <strong>remove(o)</strong></td><td>Removes by index / by value</td><td>O(n)</td></tr>\n<tr><td><strong>removeFirstOccurrence(o)</strong> / <strong>removeLastOccurrence(o)</strong></td><td>Removes the first / last equal element</td><td>O(n)</td></tr>\n<tr><td><strong>removeIf(p)</strong> / <strong>removeAll(c)</strong> / <strong>retainAll(c)</strong></td><td>Removes by rule / by collection</td><td>O(n)</td></tr>\n<tr><td><strong>contains(o)</strong> / <strong>indexOf(o)</strong> / <strong>lastIndexOf(o)</strong></td><td>Searches by value</td><td>O(n)</td></tr>\n<tr><td><strong>size()</strong> / <strong>isEmpty()</strong> / <strong>clear()</strong></td><td>Size, emptiness, remove all</td><td>O(1) / O(1) / O(n)</td></tr>\n<tr><td><strong>iterator()</strong> / <strong>listIterator()</strong> / <strong>descendingIterator()</strong></td><td>Walk forward / both ways / backwards</td><td>O(1) per step</td></tr>\n<tr><td><strong>sort(c)</strong> / <strong>replaceAll(op)</strong> / <strong>forEach(a)</strong></td><td>Inherited List helpers</td><td>O(n log n) / O(n) / O(n)</td></tr>\n<tr><td><strong>stream()</strong> / <strong>toArray()</strong> / <strong>clone()</strong></td><td>Stream, array copy, shallow copy</td><td>O(n)</td></tr>\n<tr><td><strong>reversed()</strong></td><td>A reversed view (Java 21)</td><td>O(1)</td></tr>\n</table>"
